func TestUnmarshalFlags(t *testing.T) {
	testCases := []struct {
		input  string
		output Flags
		err    bool
	}{
		{
			input: ``,
			err:   true,
		},
		{
			input:  `{}`,
			output: Flags{},
		},
		{
			input: `{
				"gfd": {}
			}`,
			output: Flags{
				CommandLineFlags{
					GFD: &GFDCommandLineFlags{},
				},
			},
		},
		{
			input: `{
				"gfd": {
					"sleepInterval": 0
				}
			}`,
			output: Flags{
				CommandLineFlags{
					GFD: &GFDCommandLineFlags{
						SleepInterval: new(Duration(0)),
					},
				},
			},
		},
		{
			input: `{
				"gfd": {
					"sleepInterval": "0s"
				}
			}`,
			output: Flags{
				CommandLineFlags{
					GFD: &GFDCommandLineFlags{
						SleepInterval: new(Duration(0)),
					},
				},
			},
		},
		{
			input: `{
				"gfd": {
					"sleepInterval": 5
				}
			}`,
			output: Flags{
				CommandLineFlags{
					GFD: &GFDCommandLineFlags{
						SleepInterval: new(Duration(5)),
					},
				},
			},
		},
		{
			input: `{
				"gfd": {
					"sleepInterval": "5s"
				}
			}`,
			output: Flags{
				CommandLineFlags{
					GFD: &GFDCommandLineFlags{
						SleepInterval: new(Duration(5 * time.Second)),
					},
				},
			},
		},
		{
			input: `{
				"gfd": {
					"sleepInterval": "infinite"
				}
			}`,
			output: Flags{
				CommandLineFlags{
					GFD: &GFDCommandLineFlags{
						SleepInterval: new(Duration(math.MaxInt64)),
					},
				},
			},
		},
		{
			input: `{
				"plugin": {
					"deviceListStrategy": "envvar"
				}
			}`,
			output: Flags{
				CommandLineFlags{
					Plugin: &PluginCommandLineFlags{
						DeviceListStrategy: &deviceListStrategyFlag{"envvar"},
					},
				},
			},
		},
		{
			input: `{
				"plugin": {
					"deviceListStrategy": ["envvar", "cdi-annotations"]
				}
			}`,
			output: Flags{
				CommandLineFlags{
					Plugin: &PluginCommandLineFlags{
						DeviceListStrategy: &deviceListStrategyFlag{"envvar", "cdi-annotations"},
					},
				},
			},
		},
	}

	for i, tc := range testCases {
		t.Run(fmt.Sprintf("test case %d", i), func(t *testing.T) {
			var output Flags
			err := json.Unmarshal([]byte(tc.input), &output)
			if tc.err {
				require.Error(t, err)
				return
			}
			require.NoError(t, err)
			require.Equal(t, tc.output, output)
		})
	}
}

func TestMarshalFlags(t *testing.T) {
	testCases := []struct {
		input  Flags
		output string
		err    bool
	}{
		{
			input: Flags{},
			output: `{
				"migStrategy": null,
				"failOnInitError": null,
				"gdrcopyEnabled": null,
				"gdsEnabled": null,
				"mofedEnabled": null,
				"useNodeFeatureAPI": null,
				"deviceDiscoveryStrategy": null
			}`,
		},
		{
			input: Flags{
				CommandLineFlags{
					GFD: &GFDCommandLineFlags{
						SleepInterval: new(Duration(0)),
					},
				},
			},
			output: `{
				"migStrategy": null,
				"failOnInitError": null,
				"gdrcopyEnabled": null,
				"gdsEnabled": null,
				"mofedEnabled": null,
				"useNodeFeatureAPI": null,
				"deviceDiscoveryStrategy": null,
				"gfd": {
					"oneshot": null,
					"noTimestamp": null,
					"outputFile": null,
					"sleepInterval": "0s",
					"machineTypeFile": null
				}
			}`,
		},
		{
			input: Flags{
				CommandLineFlags{
					GFD: &GFDCommandLineFlags{
						SleepInterval: new(Duration(5)),
					},
				},
			},
			output: `{
				"migStrategy": null,
				"failOnInitError": null,
				"gdrcopyEnabled": null,
				"gdsEnabled": null,
				"mofedEnabled": null,
				"useNodeFeatureAPI": null,
				"deviceDiscoveryStrategy": null,
				"gfd": {
					"oneshot": null,
					"noTimestamp": null,
					"outputFile": null,
					"sleepInterval": "5ns",
					"machineTypeFile": null
				}
			}`,
		},
		{
			input: Flags{
				CommandLineFlags{
					GFD: &GFDCommandLineFlags{
						SleepInterval: new(Duration(math.MaxInt64)),
					},
				},
			},
			output: `{
				"migStrategy": null,
				"failOnInitError": null,
				"gdrcopyEnabled": null,
				"gdsEnabled": null,
				"mofedEnabled": null,
				"useNodeFeatureAPI": null,
				"deviceDiscoveryStrategy": null,
				"gfd": {
					"oneshot": null,
					"noTimestamp": null,
					"outputFile": null,
					"sleepInterval": "infinite",
					"machineTypeFile": null
				}
			}`,
		},
	}

	for i, tc := range testCases {
		t.Run(fmt.Sprintf("test case %d", i), func(t *testing.T) {
			output, err := json.Marshal(tc.input)
			if tc.err {
				require.Error(t, err)
				return
			}
			require.NoError(t, err)
			require.JSONEq(t, tc.output, string(output))
		})
	}
}

