		{
			input: `{
				"name": "valid",
				"devices": "all",
				"replicas": 2
			}`,
			output: ReplicatedResource{
				Name:     NoErrorNewResourceName("valid"),
				Devices:  ReplicatedDevices{All: true},
				Replicas: 2,
			},
		},
		{
			input: `{
				"name": "valid",
				"devices": "all",
				"replicas": 2,
				"rename": "valid-shared"
			}`,
			output: ReplicatedResource{
				Name:     NoErrorNewResourceName("valid"),
				Devices:  ReplicatedDevices{All: true},
				Replicas: 2,
				Rename:   NoErrorNewResourceName("valid-shared"),
			},
		},
		{
			input: `{
				"name": "valid",
				"replicas": -1,
			}`,
			err: true,
		},
		{
			input: `{
				"name": "valid",
				"replicas": 0,
			}`,
			err: true,
		},
		{
			input: `{
				"name": "valid",
				"replicas": 2
			}`,
			output: ReplicatedResource{
				Name:     NoErrorNewResourceName("valid"),
				Devices:  ReplicatedDevices{All: true},
				Replicas: 2,
			},
		},
		{
			input: `{
				"name": "valid",
				"replicas": 2,
				"rename": "valid-shared"
			}`,
			output: ReplicatedResource{
				Name:     NoErrorNewResourceName("valid"),
				Devices:  ReplicatedDevices{All: true},
				Replicas: 2,
				Rename:   NoErrorNewResourceName("valid-shared"),
			},
		},
		{
			input: `{
				"name": "$invalid$",
				"replicas": 2,
				"rename": "valid-shared"
			}`,
			err: true,
		},
		{
			input: `{
				"name": "valid",
				"replicas": 2,
				"rename": "$invalid$"
			}`,
			err: true,
		},
	}

	for i, tc := range testCases {
		t.Run(fmt.Sprintf("test case %d", i), func(t *testing.T) {
